#include <stdio.h>
int main(){ int n=61, steps=120; double field[61]={0}, updated[61]={0}, dx=1.0, dt=0.2, ratio=0.08*0.2; field[30]=1.0; printf("step,time,center_value,total_mass,max_value,left_boundary,right_boundary,diffusion_ratio\n"); for(int s=0;s<=steps;s++){ double total=0,max=field[0]; for(int i=0;i<n;i++){ total+=field[i]*dx; if(field[i]>max) max=field[i]; } printf("%d,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",s,s*dt,field[30],total,max,field[0],field[60],ratio); for(int i=0;i<n;i++) updated[i]=field[i]; for(int i=1;i<n-1;i++) updated[i]=field[i]+ratio*(field[i+1]-2*field[i]+field[i-1]); updated[0]=0; updated[60]=0; for(int i=0;i<n;i++) field[i]=updated[i]; } return 0; }
